use vstd::prelude::*;

verus! {

/// Specification: what output string is required for a given `n`.
spec fn expected_output(n: int) -> Seq<char> {
    if n % 2 != 0 {
        seq!['b','l','a','c','k','\n']
    } else {
        seq!['w','h','i','t','e','\n','1',' ','2','\n']
    }
}

/// A tiny helper spec to state parity in a readable way.
spec fn is_odd(n: int) -> bool { n % 2 != 0 }

fn solve(n: i8) -> (result: String)
    requires
        n >= 2,
    ensures
        // The output must match exactly the required text (including newlines/spaces).
        result@ == expected_output(n as int),
{
    if (n as int) % 2 != 0 {
        let s = String::from("black\n");
        // Connect concrete string to the abstract expected Seq<char>.
        assert(s@ == seq!['b','l','a','c','k','\n']);
        // Optional sanity: this branch corresponds to odd.
        assert(is_odd(n as int));
        s
    } else {
        let s = String::from("white\n1 2\n");
        assert(s@ == seq!['w','h','i','t','e','\n','1',' ','2','\n']);
        // Optional sanity: this branch corresponds to even.
        assert(!is_odd(n as int));
        s
    }
}

} // verus!

